#include "controller.h"
#include "sensor_manager.h"
#include "actuator_manager.h"
#include "alarm_manager.h"
#include "clock_driver.h"

void Controller_Init(Controller *controller, const SystemConfig *config)
{
    if (controller == 0 || config == 0)
    {
        return;
    }

    controller->config = *config;
    controller->state = SYSTEM_IDLE;
    controller->consecutiveSensorFailures = 0U;
    controller->lastFanStopTime = 0UL;
}

void Controller_RunCycle(Controller *controller)
{
    SensorData sensors;

    if (controller == 0)
    {
        return;
    }

    if (SensorManager_Read(&sensors) != 0)
    {
        return;
    }

    if (!sensors.temperatureValid)
    {
        controller->consecutiveSensorFailures++;

        if (controller->consecutiveSensorFailures >=
            controller->config.sensorFailureLimit)
        {
            ActuatorManager_StopAll();
            AlarmManager_Activate(ALARM_SENSOR_FAILURE);
            controller->state = SYSTEM_ALARM;
        }
        return;
    }

    controller->consecutiveSensorFailures = 0U;

    if (sensors.temperature > controller->config.maxTemperature)
    {
        ActuatorManager_StopHeater();
        ActuatorManager_StartFan();
        AlarmManager_Activate(ALARM_OVER_TEMPERATURE);
        controller->state = SYSTEM_ALARM;
        return;
    }

    if (sensors.humidityValid &&
        sensors.humidity > controller->config.maxHumidity)
    {
        AlarmManager_Activate(ALARM_HIGH_HUMIDITY);
        controller->state = SYSTEM_ALARM;
        return;
    }

    if (sensors.temperature <
        controller->config.targetTemperature -
        controller->config.temperatureTolerance)
    {
        ActuatorManager_StartHeater();
        controller->state = SYSTEM_HEATING;
        return;
    }

    if (sensors.temperature >
        controller->config.targetTemperature +
        controller->config.temperatureTolerance)
    {
        if (ActuatorManager_CanStartFan(
                controller->lastFanStopTime,
                controller->config.fanCooldownSeconds))
        {
            ActuatorManager_StartFan();
            controller->state = SYSTEM_COOLING;
        }
        return;
    }

    if (controller->state == SYSTEM_COOLING)
    {
        controller->lastFanStopTime = Clock_GetSeconds();
    }

    ActuatorManager_StopAll();
    AlarmManager_Clear();
    controller->state = SYSTEM_IDLE;
}

SystemState Controller_GetState(const Controller *controller)
{
    if (controller == 0)
    {
        return SYSTEM_ALARM;
    }

    return controller->state;
}

#include "sensor_manager.h"
#include "temperature_sensor.h"
#include "humidity_sensor.h"

int SensorManager_Read(SensorData *data)
{
    if (data == 0)
    {
        return -1;
    }

    data->temperature = 0.0f;
    data->humidity = 0.0f;

    data->temperatureValid =
        (TemperatureSensor_ReadCelsius(&data->temperature) == 0);

    data->humidityValid =
        (HumiditySensor_ReadPercent(&data->humidity) == 0);

    return 0;
}

#include "actuator_manager.h"
#include "fan_driver.h"
#include "heater_driver.h"
#include "clock_driver.h"

int ActuatorManager_StartFan(void)
{
    if (HeaterDriver_Off() != 0)
    {
        return -1;
    }

    return FanDriver_On();
}

int ActuatorManager_StopFan(void)
{
    return FanDriver_Off();
}

int ActuatorManager_StartHeater(void)
{
    if (FanDriver_Off() != 0)
    {
        return -1;
    }

    return HeaterDriver_On();
}

int ActuatorManager_StopHeater(void)
{
    return HeaterDriver_Off();
}

int ActuatorManager_StopAll(void)
{
    int fanResult = FanDriver_Off();
    int heaterResult = HeaterDriver_Off();

    return (fanResult == 0 && heaterResult == 0) ? 0 : -1;
}

int ActuatorManager_CanStartFan(unsigned long lastStopTime,
                                unsigned int cooldownSeconds)
{
    unsigned long now = Clock_GetSeconds();
    return (now - lastStopTime) >= cooldownSeconds;
}

#include "alarm_manager.h"
#include "display_driver.h"
#include "buzzer_driver.h"
#include "logger_driver.h"

static AlarmType activeAlarm = ALARM_NONE;

void AlarmManager_Activate(AlarmType alarm)
{
    activeAlarm = alarm;
    DisplayDriver_ShowAlarm((int)alarm);
    BuzzerDriver_Enable();
    LoggerDriver_LogAlarm((int)alarm);
}

void AlarmManager_Clear(void)
{
    activeAlarm = ALARM_NONE;
    DisplayDriver_ClearAlarm();
    BuzzerDriver_Disable();
}

AlarmType AlarmManager_GetActiveAlarm(void)
{
    return activeAlarm;
}

#include "config.h"

void Config_LoadDefaults(SystemConfig *config)
{
    if (config == 0)
    {
        return;
    }

    config->targetTemperature = 22.0f;
    config->temperatureTolerance = 2.0f;
    config->maxTemperature = 40.0f;
    config->minTemperature = 5.0f;
    config->maxHumidity = 80.0f;
    config->fanCooldownSeconds = 30U;
    config->sensorFailureLimit = 3U;
}

#include <stdio.h>
#include "controller.h"
#include "config.h"
#include "clock_driver.h"
#include "fan_driver.h"
#include "heater_driver.h"

static const char *State_ToString(SystemState state)
{
    switch (state)
    {
        case SYSTEM_IDLE:
            return "IDLE";
        case SYSTEM_HEATING:
            return "HEATING";
        case SYSTEM_COOLING:
            return "COOLING";
        case SYSTEM_ALARM:
            return "ALARM";
        default:
            return "UNKNOWN";
    }
}

int main(void)
{
    SystemConfig config;
    Controller controller;
    unsigned int cycle;

    Config_LoadDefaults(&config);
    Controller_Init(&controller, &config);

    printf("Environmental Control Demo\n");
    printf("Target: %.1f C, tolerance: +/- %.1f C\n\n",
           config.targetTemperature,
           config.temperatureTolerance);

    for (cycle = 0U; cycle < 20U; ++cycle)
    {
        Controller_RunCycle(&controller);

        printf("Cycle %02u: state=%-8s fan=%s heater=%s\n",
               cycle + 1U,
               State_ToString(Controller_GetState(&controller)),
               FanDriver_IsOn() ? "ON" : "OFF",
               HeaterDriver_IsOn() ? "ON" : "OFF");

        Clock_DelayMs(250U);
    }

    return 0;
}
